package cn.houtu.studio;
import android.content.Context;import android.webkit.*;import android.os.*;import android.net.Uri;import com.sun.jna.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.security.*;import java.security.cert.X509Certificate;import javax.net.ssl.*;import java.util.*;import java.util.concurrent.*;import java.util.zip.*;
final class RuntimeHost {
 static volatile boolean started=false;static volatile String origin=null,error=null;static String token;static File root;static NativeBroker broker;static final Handler main=new Handler(Looper.getMainLooper());static volatile MainActivity activity;static volatile boolean visible;static final java.util.concurrent.atomic.AtomicInteger nativeOperations=new java.util.concurrent.atomic.AtomicInteger();static final ExecutorService io=Executors.newFixedThreadPool(2);static volatile boolean transfersCancelled;static WebView engine;static Memory argvMemory,argumentMemory;
 static synchronized void start(Context context){if(started)return;started=true;Context app=context.getApplicationContext();token=random();root=new File(app.getFilesDir(),"houtu");new Thread(null,()->{try{
  root.mkdirs();extract(app);File runtime=new File(root,"runtime.json");runtime.delete();new File(root,"runtime-error.txt").delete();broker=new NativeBroker(app);broker.start();
  System.setProperty("jna.boot.library.path",app.getApplicationInfo().nativeLibraryDir);System.setProperty("jna.nounpack","true");Function setenv=NativeLibrary.getInstance("c").getFunction("setenv");
  Map<String,String> env=new HashMap<>();env.put("HOUTU_RUNTIME_ROOT",root.getAbsolutePath());env.put("HOME",new File(root,"data/codex").getAbsolutePath());env.put("HOUTU_LOCAL_TOKEN",token);env.put("HOUTU_CODEX_BINARY",new File(app.getApplicationInfo().nativeLibraryDir,"libhoutu_codex.so").getAbsolutePath());env.put("HOUTU_NATIVE_ORIGIN",broker.origin());env.put("HOUTU_NATIVE_TOKEN",broker.secret);env.put("HTTP_PROXY",broker.proxyUrl());env.put("HTTPS_PROXY",broker.proxyUrl());env.put("ALL_PROXY",broker.proxyUrl());env.put("NO_PROXY","127.0.0.1,localhost");env.put("SSL_CERT_FILE",writeRoots(app).getAbsolutePath());env.put("CODEX_CA_CERTIFICATE",new File(root,"ca-bundle.pem").getAbsolutePath());env.put("TMPDIR",new File(root,"tmp").getAbsolutePath());env.put("TMP",new File(root,"tmp").getAbsolutePath());env.put("TEMP",new File(root,"tmp").getAbsolutePath());
  for(Map.Entry<String,String> e:env.entrySet())setenv.invokeInt(new Object[]{e.getKey(),e.getValue(),1});
  new Thread(()->{for(int i=0;i<300;i++){try{if(runtime.isFile()){JSONObject r=new JSONObject(read(runtime));origin=r.getString("origin");main.post(()->{if(activity!=null)activity.runtimeReady();});return;}File bad=new File(root,"runtime-error.txt");if(bad.isFile())throw new IOException(read(bad));Thread.sleep(200);}catch(Exception e){fail(e);return;}}fail(new IOException("本机图片引擎启动超时。"));},"HoutuReady").start();
  System.loadLibrary("c++_shared");NativeLibrary node=NativeLibrary.getInstance(new File(app.getApplicationInfo().nativeLibraryDir,"libnode.so").getAbsolutePath());Function start=node.getFunction("_ZN4node5StartEiPPc");String[] values={"houtu-node",new File(root,"android/boot.mjs").getAbsolutePath()};int length=0;for(String value:values)length+=value.getBytes(StandardCharsets.UTF_8).length+1;argumentMemory=new Memory(length);argvMemory=new Memory(3L*Native.POINTER_SIZE);argvMemory.clear();long offset=0;for(int i=0;i<values.length;i++){byte[] bytes=values[i].getBytes(StandardCharsets.UTF_8);argumentMemory.write(offset,bytes,0,bytes.length);argumentMemory.setByte(offset+bytes.length,(byte)0);argvMemory.setPointer((long)i*Native.POINTER_SIZE,argumentMemory.share(offset));offset+=bytes.length+1;}int status=start.invokeInt(new Object[]{2,argvMemory});if(status!=0)fail(new IOException("图片引擎已停止，代码 "+status));
 }catch(Throwable e){fail(e);}},"HoutuNode",4*1024*1024).start();}
 static void fail(Throwable e){error=e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();android.util.Log.e("HoutuRuntime",error);try{if(root!=null)Files.write(new File(root,"runtime-error.txt").toPath(),error.getBytes(StandardCharsets.UTF_8));}catch(Exception ignored){}main.post(()->{if(activity!=null)activity.runtimeFailed(error);});}
 static final class EngineClient extends WebViewClient{public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return origin==null||!r.getUrl().toString().startsWith(origin+"/");}public void onPageFinished(WebView v,String u){if(origin!=null&&u.startsWith(origin+"/"))broker.attach(v,origin);}}
 static void stopWork(){transfersCancelled=true;io.execute(()->{try{if(origin==null)return;java.net.HttpURLConnection c=(java.net.HttpURLConnection)new java.net.URL(origin+"/api/health").openConnection();c.setRequestProperty("Authorization","Bearer "+token);c.setConnectTimeout(3000);c.setReadTimeout(3000);JSONObject health;try(InputStream input=c.getInputStream()){health=new JSONObject(new String(readAll(input,65536),StandardCharsets.UTF_8));}finally{c.disconnect();}java.net.HttpURLConnection stop=(java.net.HttpURLConnection)new java.net.URL(origin+"/api/shutdown").openConnection();stop.setRequestMethod("POST");stop.setDoOutput(true);stop.setRequestProperty("Authorization","Bearer "+token);stop.setRequestProperty("Origin",origin);stop.setRequestProperty("X-Paint-CSRF",health.getString("csrf"));stop.setRequestProperty("Content-Type","application/json");stop.setConnectTimeout(3000);stop.setReadTimeout(3000);try(OutputStream out=stop.getOutputStream()){out.write(new JSONObject().put("instanceId",health.getString("instanceId")).toString().getBytes(StandardCharsets.UTF_8));}stop.getResponseCode();stop.disconnect();}catch(Exception ignored){}});}
 static String random(){byte[] b=new byte[32];new SecureRandom().nextBytes(b);StringBuilder s=new StringBuilder();for(byte v:b)s.append(String.format(Locale.ROOT,"%02x",v&255));return s.toString();}
 static String read(File f)throws IOException{return new String(Files.readAllBytes(f.toPath()),StandardCharsets.UTF_8);}
 static void extract(Context context)throws Exception{
  String expected;try(InputStream in=context.getAssets().open("bundle.json")){expected=new JSONObject(new String(readAll(in,65536),StandardCharsets.UTF_8)).getString("sha256");}
  File marker=new File(root,".bundle-sha256");if(marker.isFile()&&read(marker).equals(expected))return;
  try(InputStream raw=context.getAssets().open("houtu-project.zip");ZipInputStream zip=new ZipInputStream(new BufferedInputStream(raw))){ZipEntry e;while((e=zip.getNextEntry())!=null){String name=e.getName();if(name.startsWith("/")||name.contains("\\")||name.contains("../")||name.equals("data")||name.startsWith("data/")||name.startsWith("tmp/")||name.startsWith(".cache/"))throw new IOException("安装资源路径无效。");File out=new File(root,name);if(!out.getCanonicalPath().startsWith(root.getCanonicalPath()+File.separator))throw new IOException("安装资源越界。");if(e.isDirectory()){out.mkdirs();continue;}out.getParentFile().mkdirs();File part=new File(out.getPath()+".installing");try(OutputStream stream=new FileOutputStream(part)){copy(zip,stream,512L*1024*1024);}Files.move(part.toPath(),out.toPath(),StandardCopyOption.REPLACE_EXISTING);}}
  Files.write(marker.toPath(),expected.getBytes(StandardCharsets.UTF_8));new File(root,"tmp").mkdirs();
 }
 static File writeRoots(Context context)throws Exception{TrustManagerFactory f=TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());f.init((java.security.KeyStore)null);StringBuilder pem=new StringBuilder();for(TrustManager t:f.getTrustManagers())if(t instanceof X509TrustManager)for(X509Certificate c:((X509TrustManager)t).getAcceptedIssuers())pem.append("-----BEGIN CERTIFICATE-----\n").append(android.util.Base64.encodeToString(c.getEncoded(),android.util.Base64.DEFAULT)).append("-----END CERTIFICATE-----\n");File out=new File(root,"ca-bundle.pem");Files.write(out.toPath(),pem.toString().getBytes(StandardCharsets.US_ASCII));return out;}
 static byte[] readAll(InputStream in,int max)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();copy(in,out,max);return out.toByteArray();}
 static void copy(InputStream in,OutputStream out,long max)throws IOException{byte[] buffer=new byte[32768];long count=0;int n;while((n=in.read(buffer))!=-1){count+=n;if(count>max)throw new IOException("文件超过本机处理限制。");out.write(buffer,0,n);}}
}
